"use client";

import * as React from "react";
import { Cell, Pie, PieChart as RechartsPieChart, ResponsiveContainer, Tooltip } from "recharts";
import { cn } from "@/lib/utils";
import {
  CHART_COLORS,
  ChartFrame,
  ChartGlowFilter,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  ChartTooltipContent,
  HOVER_TRANSITION,
  markOpacity,
  useChartId,
  useChartMotion,
} from "@/components/moneytrees/charts/chart-kit";

export type PieSlice = { name: string; value: number; color?: string };

export interface SpectrumPieChartProps {
  className?: string;
  data: PieSlice[];
  variant?: "pie" | "donut";
  innerRadius?: number | string;
  paddingAngle?: number;
  cornerRadius?: number;
  showLabels?: boolean;
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  height?: number;
  formatValue?: (value: number) => string;
  /** Donut centre content. */
  center?: React.ReactNode;
}

export function PieChart({
  className,
  data,
  variant = "pie",
  innerRadius,
  paddingAngle = 2,
  cornerRadius = 6,
  showLabels = false,
  glowing = false,
  isLoading = false,
  showLegend = true,
  height,
  formatValue,
  center,
}: SpectrumPieChartProps) {
  const id = useChartId("pie");
  const { isAnimationActive, animationDuration } = useChartMotion();
  const [activeName, setActiveName] = React.useState<string | null>(null);
  const glowId = `${id}-glow`;
  const inner = innerRadius ?? (variant === "donut" ? "55%" : 0);
  const rows = data.map((item, index) => ({
    ...item,
    fill: item.color ?? CHART_COLORS[index % CHART_COLORS.length]!,
  }));

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend ? (
        <ChartLegend items={rows.map((item) => ({ label: item.name, color: item.fill }))} />
      ) : null}
      {isLoading ? (
        <ChartLoadingBars count={6} />
      ) : (
        <ChartPlotSurface>
          <ResponsiveContainer width="100%" height="100%">
            <RechartsPieChart>
              <defs>{glowing ? <ChartGlowFilter id={glowId} /> : null}</defs>
              <Tooltip content={<ChartTooltipContent formatValue={formatValue} />} />
              <Pie
                data={rows}
                dataKey="value"
                nameKey="name"
                innerRadius={inner}
                outerRadius={showLabels ? "64%" : "78%"}
                paddingAngle={paddingAngle}
                cornerRadius={cornerRadius}
                isAnimationActive={isAnimationActive}
                animationDuration={animationDuration}
                animationEasing="ease-out"
                label={
                  showLabels
                    ? ({ name, percent }) => `${name} ${Math.round((percent ?? 0) * 100)}%`
                    : false
                }
                labelLine={showLabels}
                filter={glowing ? `url(#${glowId})` : undefined}
                onMouseLeave={() => setActiveName(null)}
              >
                {rows.map((item) => (
                  <Cell
                    key={item.name}
                    fill={item.fill}
                    stroke="var(--spectrum-chart-surface)"
                    strokeWidth={1.5}
                    style={{
                      opacity: markOpacity(activeName, item.name),
                      transition: HOVER_TRANSITION,
                      cursor: "pointer",
                    }}
                    onMouseEnter={() => setActiveName(item.name)}
                  />
                ))}
              </Pie>
            </RechartsPieChart>
          </ResponsiveContainer>
          {center && variant === "donut" ? (
            <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
              {center}
            </div>
          ) : null}
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}
